1	//! Data export logic for codeflow Phase 6.
2	//!
3	//! Supports three formats: JSON, CSV, HTML dashboard.
4	
5	use anyhow::{Context, Result};
6	use serde::Serialize;
7	
8	use crate::compliance::report_common::query_provenance_records;
9	use crate::core::cost_store::CostStore;
10	use crate::core::provenance::ProvenanceRecord;
11	
12	// ── Public types ──────────────────────────────────────────────────────────────
13	
14	/// Aggregated cost by model.
15	#[derive(Debug, Clone, Serialize)]
16	pub struct ModelCostSummary {
17	    pub model_id: String,
18	    pub total_usd: f64,
19	    pub total_tokens: u64,
20	}
21	
22	/// High-level statistics for the exported range.
23	#[derive(Debug, Clone, Serialize)]
24	pub struct ExportStats {
25	    pub total_files: u64,
26	    pub total_cost_usd: f64,
27	    pub ai_pct: f64,
28	    pub top_model: String,
29	    /// (from_rfc3339, to_rfc3339)
30	    pub date_range: (String, String),
31	}
32	
33	// ── Data loading ──────────────────────────────────────────────────────────────
34	
35	/// Load provenance records and cost summaries for a given range / project filter.
36	///
37	/// Both databases are opened independently; a missing DB yields empty data with a hint message.
38	pub fn load_export_data(
39	    since_rfc3339: Option<&str>,
40	    project: Option<&str>,
41	) -> Result<(Vec<ProvenanceRecord>, Vec<ModelCostSummary>, ExportStats)> {
42	    // Provenance records — graceful empty on missing DB.
43	    let records = query_provenance_records(since_rfc3339, project, None)
44	        .context("failed to query provenance records")?;
45	
46	    // Cost summaries by model — graceful empty on missing DB.
47	    let cost_summaries: Vec<ModelCostSummary> = match CostStore::new() {
48	        Ok(store) => store
49	            .summarize_by_model()
50	            .unwrap_or_default()
51	            .into_iter()
52	            .map(|s| ModelCostSummary {
53	                model_id: s.key,
54	                total_usd: s.total_cost_usd,
55	                total_tokens: s.input_tokens + s.output_tokens,
56	            })
57	            .collect(),
58	        Err(_) => Vec::new(),
59	    };
60	
61	    let stats = build_stats(&records, &cost_summaries, since_rfc3339);
62	    Ok((records, cost_summaries, stats))
63	}
64	
65	fn build_stats(
66	    records: &[ProvenanceRecord],
67	    costs: &[ModelCostSummary],
68	    since_rfc3339: Option<&str>,
69	) -> ExportStats {
70	    let total_files = records.len() as u64;
71	    let total_cost_usd: f64 = costs.iter().map(|c| c.total_usd).sum();
72	
73	    let ai_count = records
74	        .iter()
75	        .filter(|r| matches!(r.contributor_type, crate::core::provenance::ContributorType::Ai))
76	        .count();
77	    let ai_pct = if total_files > 0 {
78	        (ai_count as f64 / total_files as f64) * 100.0
79	    } else {
80	        0.0
81	    };
82	
83	    let top_model = costs
84	        .iter()
85	        .max_by(|a, b| a.total_usd.partial_cmp(&b.total_usd).unwrap_or(std::cmp::Ordering::Equal))
86	        .map(|c| c.model_id.clone())
87	        .unwrap_or_else(|| "none".to_string());
88	
89	    let now = chrono::Utc::now().to_rfc3339();
90	    let from = since_rfc3339.unwrap_or("epoch").to_string();
91	
92	    ExportStats {
93	        total_files,
94	        total_cost_usd,
95	        ai_pct,
96	        top_model,
97	        date_range: (from, now),
98	    }
99	}
100	
101	// ── JSON export ───────────────────────────────────────────────────────────────
102	
103	pub fn export_json(
104	    provenance: &[ProvenanceRecord],
105	    costs: &[ModelCostSummary],
106	    stats: &ExportStats,
107	) -> Result<String> {
108	    let payload = serde_json::json!({
109	        "schema": "rtk-codeflow-export-v1",
110	        "generated_at": chrono::Utc::now().to_rfc3339(),
111	        "stats": stats,
112	        "cost_by_model": costs,
113	        "provenance": provenance,
114	    });
115	    serde_json::to_string_pretty(&payload).context("failed to serialize JSON export")
116	}
117	
118	// ── CSV export ────────────────────────────────────────────────────────────────
119	
120	pub fn export_csv(provenance: &[ProvenanceRecord]) -> Result<String> {
121	    let mut out = String::new();
122	    // Header
123	    out.push_str(
124	        "id,model_id,model_version,file_path,start_line,end_line,contributor_type,developer_id,session_id,timestamp\n",
125	    );
126	    for r in provenance {
127	        let id = r.id.map(|n| n.to_string()).unwrap_or_default();
128	        // Escape fields that may contain commas/quotes
129	        let fields = [
130	            id.as_str(),
131	            &r.model_id,
132	            &r.model_version,
133	            &r.file_path,
134	            &r.start_line.to_string(),
135	            &r.end_line.to_string(),
136	            r.contributor_type.as_str(),
137	            &r.developer_id,
138	            &r.session_id,
139	            &r.timestamp,
140	        ];
141	        let row: Vec<String> = fields.iter().map(|f| csv_escape(f)).collect();
142	        out.push_str(&row.join(","));
143	        out.push('\n');
144	    }
145	    Ok(out)
146	}
147	
148	fn csv_escape(s: &str) -> String {
149	    if s.contains(',') || s.contains('"') || s.contains('\n') {
150	        format!("\"{}\"", s.replace('"', "\"\""))
151	    } else {
152	        s.to_string()
153	    }
154	}
