193	// ── Data builders ─────────────────────────────────────────────────────────────
194	
195	fn build_data_json(
196	    provenance: &[ProvenanceRecord],
197	    costs: &[ModelCostSummary],
198	    stats: &ExportStats,
199	) -> Result<String> {
200	    // Aggregate cost by day from provenance timestamps
201	    let mut day_map: std::collections::BTreeMap<String, f64> = std::collections::BTreeMap::new();
202	    // We don't have per-record cost, so we spread total cost evenly across days for the line chart.
203	    // This is a best-effort approximation; accurate per-day cost requires joining cost_records.
204	    for r in provenance {
205	        let day = r.timestamp.get(..10).unwrap_or("unknown").to_string();
206	        day_map.entry(day).or_insert(0.0);
207	    }
208	    // If we have cost summaries but no day breakdown, add total cost to the most recent day.
209	    if !costs.is_empty() && !day_map.is_empty() {
210	        let last_day = day_map.keys().last().cloned().unwrap_or_default();
211	        *day_map.entry(last_day).or_insert(0.0) += stats.total_cost_usd;
212	    }
213	
214	    let cost_by_day: Vec<serde_json::Value> = day_map
215	        .into_iter()
216	        .map(|(date, cost)| serde_json::json!({"date": date, "cost": cost}))
217	        .collect();
218	
219	    let payload = serde_json::json!({
220	        "stats": stats,
221	        "cost_by_model": costs,
222	        "cost_by_day": cost_by_day,
223	    });
224	
225	    serde_json::to_string(&payload).map_err(|e| anyhow::anyhow!("JSON serialize: {}", e))
226	}
227	
228	fn build_provenance_rows(provenance: &[ProvenanceRecord], limit: usize) -> String {
229	    let recent: Vec<_> = provenance.iter().rev().take(limit).collect();
230	    if recent.is_empty() {
231	        return r#"      <tr><td colspan="5" class="empty">No provenance records in this range.</td></tr>"#
232	            .to_string();
233	    }
234	    recent
235	        .iter()
236	        .map(|r| {
237	            let badge_class = match r.contributor_type {
238	                crate::core::provenance::ContributorType::Ai => "badge-ai",
239	                crate::core::provenance::ContributorType::Human => "badge-human",
240	                _ => "badge-mixed",
241	            };
242	            format!(
243	                "      <tr><td>{}</td><td>{}</td><td><span class=\"badge {}\">{}</span></td><td>{}</td><td>{}</td></tr>",
244	                html_escape(&r.file_path),
245	                html_escape(&r.model_id),
246	                badge_class,
247	                r.contributor_type.as_str(),
248	                html_escape(&r.developer_id),
249	                html_escape(r.timestamp.get(..19).unwrap_or(&r.timestamp)),
250	            )
251	        })
252	        .collect::<Vec<_>>()
253	        .join("\n")
254	}
255	
256	fn build_top_cost_rows(
257	    _provenance: &[ProvenanceRecord],
258	    costs: &[ModelCostSummary],
259	    limit: usize,
260	) -> String {
261	    let top: Vec<_> = costs.iter().take(limit).collect();
262	    if top.is_empty() {
263	        return r#"      <tr><td colspan="3" class="empty">No cost data available.</td></tr>"#
264	            .to_string();
265	    }
266	    top.iter()
267	        .map(|c| {
268	            format!(
269	                "      <tr><td>{}</td><td>${:.6}</td><td>{}</td></tr>",
270	                html_escape(&c.model_id),
271	                c.total_usd,
272	                c.total_tokens,
273	            )
274	        })
275	        .collect::<Vec<_>>()
276	        .join("\n")
277	}
278	
279	fn html_escape(s: &str) -> String {
280	    s.replace('&', "&amp;")
281	        .replace('<', "&lt;")
282	        .replace('>', "&gt;")
283	        .replace('"', "&quot;")
284	}
