2	//!
3	//! Usage:
4	//!   rtk export                          — HTML dashboard, last 90 days
5	//!   rtk export --format json|csv|html   — explicit format
6	//!   rtk export --range 30d|90d|1y|all   — date range
7	//!   rtk export --project <name>         — filter by project path substring
8	//!   rtk export --output <dir>           — output directory (default: ./codeflow-export/)
9	//!   rtk export --json                   — when format=json, print to stdout
10	
11	use anyhow::{Context, Result};
12	use colored::Colorize;
13	
14	use crate::compliance::report_common::range_to_since;
15	use crate::core::exporter::{export_csv, export_html, export_json, load_export_data};
16	
17	// ── Public args struct ────────────────────────────────────────────────────────
18	
19	pub struct ExportArgs {
20	    pub format: String,
21	    pub range: String,
22	    pub project: Option<String>,
23	    pub output: Option<String>,
24	    /// When format=json, print to stdout instead of writing a file.
25	    pub json_stdout: bool,
26	}
27	
28	impl Default for ExportArgs {
29	    fn default() -> Self {
30	        Self {
31	            format: "html".to_string(),
32	            range: "90d".to_string(),
33	            project: None,
34	            output: None,
35	            json_stdout: false,
36	        }
37	    }
38	}
39	
40	// ── Entry point ───────────────────────────────────────────────────────────────
41	
42	pub fn run(args: &ExportArgs) -> Result<i32> {
43	    let since = range_to_since(&args.range);
44	    let since_str = since.as_deref();
45	
46	    let (records, costs, stats) =
47	        load_export_data(since_str, args.project.as_deref())
48	            .context("failed to load export data")?;
49	
50	    let fmt = args.format.to_lowercase();
51	
52	    // JSON → stdout shortcut
53	    if fmt == "json" && args.json_stdout {
54	        let content = export_json(&records, &costs, &stats)
55	            .context("failed to generate JSON export")?;
56	        println!("{}", content);
57	        return Ok(0);
58	    }
59	
60	    // Determine output directory
61	    let out_dir = std::path::PathBuf::from(
62	        args.output.as_deref().unwrap_or("codeflow-export"),
63	    );
64	    std::fs::create_dir_all(&out_dir)
65	        .with_context(|| format!("failed to create output dir: {}", out_dir.display()))?;
66	
67	    // Build timestamped filename
68	    let ts = chrono::Utc::now().format("%Y%m%dT%H%M%SZ").to_string();
69	    let (content, ext) = match fmt.as_str() {
70	        "json" => (
71	            export_json(&records, &costs, &stats).context("JSON export failed")?,
72	            "json",
73	        ),
74	        "csv" => (
75	            export_csv(&records).context("CSV export failed")?,
76	            "csv",
77	        ),
78	        "html" | _ => (
79	            export_html(&records, &costs, &stats).context("HTML export failed")?,
80	            "html",
81	        ),
82	    };
83	
84	    let filename = format!("{}-codeflow-{}.{}", ts, fmt, ext);
85	    let out_path = out_dir.join(&filename);
86	
87	    std::fs::write(&out_path, &content)
88	        .with_context(|| format!("failed to write export: {}", out_path.display()))?;
89	
90	    // Human-readable summary
91	    println!("{}", "Codeflow Export".bold());
92	    println!("{}", "─".repeat(50));
93	    println!("  Format:    {}", fmt.cyan().bold());
94	    println!("  Range:     {}", args.range);
95	    println!("  Records:   {}", stats.total_files.to_string().yellow());
96	    println!(
97	        "  Cost:      {}",
98	        format!("${:.4}", stats.total_cost_usd).yellow()
99	    );
100	    println!("  AI Code:   {:.1}%", stats.ai_pct);
101	    println!();
102	    println!("  Output:    {}", out_path.display().to_string().green().bold());
103	
104	    if ext == "html" {
105	        println!();
106	        println!(
107	            "  {}",
108	            "Open in browser: file://".dimmed().to_string()
109	                + &out_path
110	                    .canonicalize()
111	                    .unwrap_or(out_path.clone())
112	                    .display()
113	                    .to_string()
114	        );
115	    }
116	
117	    if stats.total_files == 0 {
118	        println!();
119	        println!(
120	            "  {}",
121	            "No records found for this range. Run with RTK_CODEFLOW=1 to start recording."
122	                .dimmed()
123	        );
124	    }
125	
126	    Ok(0)
127	}
