1	//! `rtk serve` — local HTTP server for the live codeflow dashboard (Phase 6).
2	//!
3	//! Usage:
4	//!   rtk serve             — start on port 3141
5	//!   rtk serve --port <N>  — custom port
6	//!
7	//! Single-threaded blocking server. Ctrl+C to stop.
8	//! On each GET / request the HTML dashboard is regenerated from current DB state.
9	
10	use anyhow::{Context, Result};
11	use colored::Colorize;
12	use std::io::{BufRead, BufReader, Write};
13	use std::net::{TcpListener, TcpStream};
14	
15	use crate::core::exporter::{export_html, load_export_data};
16	
17	// ── Public args struct ────────────────────────────────────────────────────────
18	
19	pub struct ServeArgs {
20	    pub port: u16,
21	}
22	
23	impl Default for ServeArgs {
24	    fn default() -> Self {
25	        Self { port: 3141 }
26	    }
27	}
28	
29	// ── Entry point ───────────────────────────────────────────────────────────────
30	
31	pub fn run(args: &ServeArgs) -> Result<i32> {
32	    let addr = format!("127.0.0.1:{}", args.port);
33	    let listener = TcpListener::bind(&addr)
34	        .with_context(|| format!("failed to bind to {}", addr))?;
35	
36	    println!("{}", "RTK Codeflow — Live Dashboard".bold());
37	    println!("{}", "─".repeat(50));
38	    println!(
39	        "  {}  {}",
40	        "Dashboard available at".dimmed(),
41	        format!("http://localhost:{}", args.port).cyan().bold()
42	    );
43	    println!("  {}", "Press Ctrl+C to stop.".dimmed());
44	    println!();
45	
46	    for stream in listener.incoming() {
47	        match stream {
48	            Ok(s) => {
49	                if let Err(e) = handle_connection(s) {
50	                    eprintln!("[rtk serve] connection error: {:#}", e);
51	                }
52	            }
53	            Err(e) => {
54	                eprintln!("[rtk serve] accept error: {:#}", e);
55	            }
56	        }
57	    }
58	
59	    Ok(0)
60	}
61	
62	// ── HTTP request handler ──────────────────────────────────────────────────────
63	
64	fn handle_connection(mut stream: TcpStream) -> Result<()> {
65	    let buf_reader = BufReader::new(stream.try_clone().context("clone stream")?);
66	
67	    // Read request line + headers (consume until blank line)
68	    let mut request_line = String::new();
69	    let mut lines = buf_reader.lines();
70	    if let Some(Ok(line)) = lines.next() {
71	        request_line = line;
72	    }
73	    // Drain headers
74	    for line in lines {
75	        match line {
76	            Ok(l) if l.is_empty() => break,
77	            Ok(_) => {}
78	            Err(_) => break,
79	        }
80	    }
81	
82	    // Route: only serve GET /
83	    let path = parse_path(&request_line);
84	    let (status, content_type, body) = match path.as_deref() {
85	        Some("/") | Some("") => {
86	            let html = generate_dashboard().unwrap_or_else(|e| {
87	                format!(
88	                    "<!DOCTYPE html><html><body><pre>Error generating dashboard:\n{:#}</pre></body></html>",
89	                    e
90	                )
91	            });
92	            ("200 OK", "text/html; charset=utf-8", html)
93	        }
94	        Some("/health") => ("200 OK", "text/plain", "ok".to_string()),
95	        _ => (
96	            "404 Not Found",
97	            "text/plain",
98	            "Not found. Navigate to /".to_string(),
99	        ),
100	    };
101	
102	    let response = format!(
103	        "HTTP/1.1 {}\r\nContent-Type: {}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
104	        status,
105	        content_type,
106	        body.len(),
107	        body
108	    );
109	
110	    stream
111	        .write_all(response.as_bytes())
112	        .context("write response")?;
113	
114	    Ok(())
115	}
116	
117	fn parse_path(request_line: &str) -> Option<String> {
118	    // "GET /path HTTP/1.1"
119	    let mut parts = request_line.splitn(3, ' ');
